  },
  {
    "root_cause_class": "insufficient_evidence",
    "summary": "Need more data on CPU usage trends between versions.",
    "supporting": [],
    "contradicting": ["ev-container_cpu", "ev-revision_health"],
    "missing": ["ev-revision_health"],
    "status": "refuted"
